create policy "Admins read kb files" on storage.objects for select to authenticated using (bucket_id = 'kb-files' and public.has_role(auth.uid(),'admin'));
create policy "Admins upload kb files" on storage.objects for insert to authenticated with check (bucket_id = 'kb-files' and public.has_role(auth.uid(),'admin'));
create policy "Admins delete kb files" on storage.objects for delete to authenticated using (bucket_id = 'kb-files' and public.has_role(auth.uid(),'admin'));